BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT118-S1-Q3$batch05$ AND q.stimulus=$batch05$A reason Larson cannot do the assignment is that she has an unavoidable scheduling conflict. On the other hand, a reason Franks cannot do the assignment is that he does not quite have the assertiveness the task requires. So, the task must be assigned to Parker, the only supervisor in the shipping department other than Larson and Franks.$batch05$ AND q.prompt=$batch05$The argument depends on assuming which one of the following?$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT118-S1-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT118-S1-Q3$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S1-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT118-S1-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The task must go to Parker.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Larson has an unavoidable scheduling conflict. Franks lacks the needed assertiveness. Parker is the only other supervisor in the shipping department.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The author crosses off two names and declares the third the winner. That only works if the list of candidates is complete. Why does it have to be a shipping supervisor at all? Someone from another department, or a non-supervisor, could take it. This is a process-of-elimination argument, and those always assume the field of options is closed.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: the task can only go to a supervisor in the shipping department.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT118-S1-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Larson is already out because of her schedule. Her assertiveness changes nothing.$batch05$), ($batch05$B$batch05$, $batch05$Negate it: "the task *can* be assigned to someone outside the shipping supervisors." Then knocking out Larson and Franks does not leave only Parker, and "must" falls apart.$batch05$), ($batch05$C$batch05$, $batch05$What would happen in a world where Franks were more assertive does not matter. In this one, he is out.$batch05$), ($batch05$D$batch05$, $batch05$The argument only needs Larson's conflict, which is unavoidable, to rule her out. It does not need every conflict of every kind to disqualify someone.$batch05$), ($batch05$E$batch05$, $batch05$This rules out outsiders for one reason only, assertiveness. An outsider could still be barred for some other reason, so the argument does not need this. It needs the broader point in B.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT118-S1-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
